using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;using ProMaxx2.QA.Domain.Identity;using ProMaxx2.QA.Domain.Projects;using ProMaxx2.QA.Domain.Requirements;using ProMaxx2.QA.Domain.TestManagement;
namespace ProMaxx2.QA.Infrastructure.Persistence;
public sealed class TestCaseConfiguration:IEntityTypeConfiguration<TestCase>{public void Configure(EntityTypeBuilder<TestCase>b){b.ToTable("TestCases");b.HasKey(x=>x.TestCaseId);b.Property(x=>x.TestCaseId).HasDefaultValueSql("NEWSEQUENTIALID()");b.Property(x=>x.TestCaseCode).HasMaxLength(100).IsRequired();b.HasIndex(x=>new{x.ProjectId,x.TestCaseCode}).IsUnique();b.Property(x=>x.Title).HasMaxLength(300).IsRequired();b.Property(x=>x.Priority).HasMaxLength(20);b.Property(x=>x.TestType).HasMaxLength(50);b.Property(x=>x.Status).HasMaxLength(30);b.Property(x=>x.CreatedAt).HasPrecision(0);b.Property(x=>x.UpdatedAt).HasPrecision(0);b.HasOne<Project>().WithMany().HasForeignKey(x=>x.ProjectId).OnDelete(DeleteBehavior.Restrict);b.HasOne<ProductModule>().WithMany().HasForeignKey(x=>x.ModuleId).OnDelete(DeleteBehavior.Restrict);b.HasOne<User>().WithMany().HasForeignKey(x=>x.OwnerUserId).OnDelete(DeleteBehavior.Restrict);}}
public sealed class TestStepConfiguration:IEntityTypeConfiguration<TestStep>{public void Configure(EntityTypeBuilder<TestStep>b){b.ToTable("TestSteps");b.HasKey(x=>x.TestStepId);b.Property(x=>x.TestStepId).HasDefaultValueSql("NEWSEQUENTIALID()");b.HasIndex(x=>new{x.TestCaseId,x.RevisionNo,x.StepNo}).IsUnique();b.Property(x=>x.Action).IsRequired();b.Property(x=>x.ExpectedResult).IsRequired();b.HasOne(x=>x.TestCase).WithMany(x=>x.Steps).HasForeignKey(x=>x.TestCaseId).OnDelete(DeleteBehavior.Cascade);}}
public sealed class RequirementTestCaseConfiguration:IEntityTypeConfiguration<RequirementTestCase>{public void Configure(EntityTypeBuilder<RequirementTestCase>b){b.ToTable("RequirementTestCases");b.HasKey(x=>new{x.RequirementId,x.TestCaseId});b.Property(x=>x.CoverageType).HasMaxLength(30);b.Property(x=>x.CreatedAt).HasPrecision(0);b.HasOne<Requirement>().WithMany().HasForeignKey(x=>x.RequirementId).OnDelete(DeleteBehavior.Cascade);b.HasOne<TestCase>().WithMany().HasForeignKey(x=>x.TestCaseId).OnDelete(DeleteBehavior.Cascade);}}
public sealed class TestCaseRevisionConfiguration:IEntityTypeConfiguration<TestCaseRevision>{public void Configure(EntityTypeBuilder<TestCaseRevision>b){b.ToTable("TestCaseRevisions");b.HasKey(x=>x.TestCaseRevisionId);b.Property(x=>x.TestCaseRevisionId).HasDefaultValueSql("NEWSEQUENTIALID()");b.HasIndex(x=>new{x.TestCaseId,x.RevisionNo}).IsUnique();b.Property(x=>x.ChangeReason).HasMaxLength(500).IsRequired();b.Property(x=>x.ChangedAt).HasPrecision(0);b.HasOne(x=>x.TestCase).WithMany(x=>x.Revisions).HasForeignKey(x=>x.TestCaseId).OnDelete(DeleteBehavior.Cascade);b.HasOne<User>().WithMany().HasForeignKey(x=>x.ChangedBy).OnDelete(DeleteBehavior.Restrict);}}
